default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\System\Currentcontrolset\Services\Lanmanserver\Parameters' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('SMBServerNameHardeningLevel', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]$ODV_smb_server_name_hardening_level)) {
    Write-Output 'Mismatch: HKLM:\System\Currentcontrolset\Services\Lanmanserver\Parameters [SMBServerNameHardeningLevel]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if .Vars.win11cis_level_1 }}
  {{ if .Vars.win11cis_rule_2_3_9_5 }}
registry:
  HKLM\SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters\SMBServerNameHardeningLevel:
    title: "2.3.9.5 | Ensure 'Microsoft network server: Server SPN target name validation level' is set to 'Accept if provided by client' or higher | SMBServerNameHardeningLevel"
    exists: true
    value: {{ .Vars.win11cis_smb_server_name_hardening_level }}
    type: REG_DWORD
    meta:
      workstation: 1
      CIS_ID:
        - 2.3.9.5
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\System\Currentcontrolset\Services\Lanmanserver\Parameters')) {
    New-Item -Path 'HKLM:\System\Currentcontrolset\Services\Lanmanserver\Parameters' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\System\Currentcontrolset\Services\Lanmanserver\Parameters' -Name 'SMBServerNameHardeningLevel' -Value $ODV_smb_server_name_hardening_level -PropertyType DWord -Force | Out-Null
exit 0
